    "name": "乌西雅、约坦、亚哈斯、希西家",
    "aka": [
      "四位犹大王"
    ],
    "star": 3,
    "role": "本章的时间刻度",
    "relation": "父子相继的南国君王；亚哈斯是希西家之父，乌西雅是约坦之父",
