    "key": [
      "赛14:28-32",
      "代下28:18",
      "摩1:6-8"
    ],
    "one": "亚述的杖折断了，他们以为可以松口气；先知说，从蛇根里还要长出更毒的蛇。",
    "avoid": "非利士人不是今天的巴勒斯坦人，二者相隔两千多年；不要用本章为现代民族冲突背书。",
