    "first": "王下16:1",
    "key": [
      "赛7:1-12",
      "王下16:7-9",
      "代下28:16-21"
    ],
    "one": "他在敌军压境时心像风中的树，却宁可信亚述的军队，也不肯向神求一个兆头；他的敬虔话掩盖了不信。",
    "avoid": "不要与希西家混淆：亚哈斯向亚述求援，希西家则在 701 年亲身经历亚述围城；两人对神的态度也相反。",
