    "one": "他的名是一句话：「掳掠速临，抢夺快到」。孩子还没学会叫爸爸，亚述的战利品就已经被搬走。",
    "avoid": "他是人名而非口号或咒语；不要与 7:3 的「施亚雅述」（以赛亚的长子，意为「余民必归回」）混淆——两个儿子，两个名字，两条信息。",
