    "relation": "34:5 他听见示剑玷辱底拿，「闭口不言，等他们回来」；34:18–19 哈抹父子用聘金与割礼拖延；34:25–29 西缅和利未杀了城中男丁并掳掠；34:30 他把后果算到自己头上：「你们连累我，使我在这地的居民中……有了臭名」",
