    "relation": "10:1 亚伦的儿子拿答、亚比户各拿自己的香炉，盛上火，加上香，在耶和华面前献上凡火，是耶和华没有吩咐他们的；10:2 火从耶和华面前出来，把他们烧灭；10:5 他们的尸首被抬到营外；10:17–19 摩西向耶和华代求，耶和华说「他们献的凡火，我却不喜悦」",
