    "role": "本章的对象 · 献祭制度和血都要落到他们身上",
    "relation": "17:2 摩西要晓谕以色列众人；17:3 凡以色列家中的人宰牛羊；17:8 以色列家中的人或寄居在中间的外人都受同一条例；17:7「不可再献祭给他们行邪淫所随从的鬼魔」",
