    "one": "他们刚从旷野走出来，献祭还是野地里的老习惯；这一章把野地献祭收回到会幕门口，把献祭从「到处都可以」变成「只有一扇门」。",
    "avoid": "不要把「不可吃血」读成饮食禁忌；17:11–14 的理由是「生命是在血中」，指向献祭，不是说血有毒。也不要把 17:5 理解成禁止在家中摆宴——那是祭物与和平祭的规矩。",
